// Embeds the Vitals icon into this binary.
//
// rustc writes no resource section, so a program that never runs a resource
// compiler is drawn with Windows' generic application icon — in Explorer, in
// Task Manager, and in the Windows Defender Firewall prompt that `vitals serve`
// raises the first time it binds a socket. The desktop app escapes this because
// tauri-build embeds an icon for it; this binary does not go through Tauri.
//
// The `.ico` is the same brand artefact tauri-build embeds into the desktop
// binary (generated by brand/scripts/build.mjs, listed in tauri.conf.json under
// bundle.icon) and it is embedded under the same resource id, so every Vitals
// executable resolves the same mark. Both `apps/<name>` and `crates/<name>` sit
// two levels below the workspace root, which is why one relative path reaches
// the icon from here. This file is byte-identical to its two copies in
// apps/watchdog and crates/vitals-sensors; scripts/check-drift.ps1 enforces
// that, because a binary that silently loses its icon looks like a bug Windows
// found rather than one we shipped.
fn main() {
    // Gate on the TARGET, not on the host: CI builds this workspace on Ubuntu to
    // keep the trait boundary honest, and never wants a resource compiler there.
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows") {
        return;
    }

    let Ok(manifest_dir) = std::env::var("CARGO_MANIFEST_DIR") else {
        panic!("CARGO_MANIFEST_DIR is unset, so this is not running as a build script");
    };
    let icon =
        std::path::Path::new(&manifest_dir).join("../../apps/desktop/src-tauri/icons/icon.ico");
    // The icon lives outside this package, so cargo cannot infer that
    // regenerating it should rebuild this binary.
    println!("cargo:rerun-if-changed={}", icon.display());
    assert!(
        icon.is_file(),
        "the brand icon is missing at {} — brand/scripts/build.mjs regenerates it",
        icon.display()
    );

    let mut resource = tauri_winres::WindowsResource::new();
    // `new()` fills the version block from this package's Cargo.toml, which
    // names the crate (`vitals-cli`, `vitals-watchdog`, `vitals-sensors`). The
    // name a user reads in the firewall prompt is the product, so say so; the
    // description stays this package's own, which is the more useful line.
    resource.set("ProductName", "Vitals");
    resource.set_icon(&icon.display().to_string());
    if let Err(error) = resource.compile() {
        panic!("embedding the Vitals icon into this binary failed: {error}");
    }
}
